ALTER TABLE public.cash_registers ADD COLUMN operator_id uuid, ADD COLUMN operator_name text NOT NULL DEFAULT '', ADD COLUMN closing_report jsonb;
ALTER TABLE public.cash_movements ADD COLUMN operator_id uuid, ADD COLUMN transaction_id uuid REFERENCES public.transactions(id);
CREATE UNIQUE INDEX cash_movement_transaction ON public.cash_movements(transaction_id) WHERE transaction_id IS NOT NULL;
ALTER TABLE public.ingredients ADD COLUMN business_unit text NOT NULL DEFAULT 'lanchonete' CHECK(business_unit IN ('pousada','lanchonete'));
CREATE POLICY "Account stock admin write" ON public.ingredients FOR ALL TO authenticated USING(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Account cash read" ON public.cash_registers FOR SELECT TO authenticated USING(user_id=public.account_owner());
CREATE POLICY "Account movements read" ON public.cash_movements FOR SELECT TO authenticated USING(user_id=public.account_owner());
REVOKE INSERT, UPDATE, DELETE ON public.cash_registers, public.cash_movements FROM authenticated;
CREATE FUNCTION public.cash_method(_method text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE lower(coalesce(_method,'')) WHEN 'dinheiro' THEN 'Dinheiro' WHEN 'pix' THEN 'Pix' WHEN 'cartão de crédito' THEN 'Crédito' WHEN 'cartão de débito' THEN 'Débito' WHEN 'crédito' THEN 'Crédito' WHEN 'débito' THEN 'Débito' ELSE 'Outros' END $$;
CREATE FUNCTION public.open_cash(_amount numeric, _operator text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL OR _amount IS NULL OR _amount<0 OR _amount>999999999 OR length(trim(_operator)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Dados de abertura inválidos'; END IF; PERFORM pg_advisory_xact_lock(hashtext(public.account_owner()::text)); INSERT INTO public.cash_registers(user_id,opening_amount,operator_id,operator_name) VALUES(public.account_owner(),round(_amount,2),auth.uid(),trim(_operator)) RETURNING id INTO rid; RETURN rid; END $$;
CREATE FUNCTION public.move_cash(_register uuid,_type text,_amount numeric,_description text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.cash_registers; BEGIN SELECT * INTO r FROM public.cash_registers WHERE id=_register FOR UPDATE; IF auth.uid() IS NULL OR NOT FOUND OR r.user_id<>public.account_owner() OR r.status<>'aberto' THEN RAISE EXCEPTION 'Caixa fechado ou sem acesso'; END IF; IF _type NOT IN('sangria','suprimento') OR _amount IS NULL OR _amount<=0 OR _amount>999999999 OR length(trim(_description)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Movimentação inválida'; END IF; INSERT INTO public.cash_movements(user_id,cash_register_id,movement_type,amount,payment_method,description,operator_id) VALUES(r.user_id,r.id,_type,round(_amount,2),'Dinheiro',trim(_description),auth.uid()); END $$;
CREATE FUNCTION public.close_cash(_register uuid,_counts jsonb,_notes text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.cash_registers; m text; expected numeric; counted numeric; report jsonb:='{}'; et numeric:=0; ct numeric:=0; BEGIN SELECT * INTO r FROM public.cash_registers WHERE id=_register FOR UPDATE; IF auth.uid() IS NULL OR NOT FOUND OR r.user_id<>public.account_owner() OR r.status<>'aberto' THEN RAISE EXCEPTION 'Caixa fechado ou sem acesso'; END IF; IF jsonb_typeof(_counts)<>'object' OR length(coalesce(_notes,''))>2000 THEN RAISE EXCEPTION 'Conferência inválida'; END IF; FOREACH m IN ARRAY ARRAY['Dinheiro','Pix','Crédito','Débito','Outros'] LOOP IF NOT (_counts ? m) THEN RAISE EXCEPTION 'Preencha todas as formas de pagamento'; END IF; counted:=(_counts->>m)::numeric; IF counted IS NULL OR counted<0 OR counted>999999999 THEN RAISE EXCEPTION 'Valor inválido'; END IF; counted:=round(counted,2); SELECT coalesce(sum(CASE WHEN movement_type IN('venda','suprimento') THEN amount ELSE -amount END),0) INTO expected FROM public.cash_movements WHERE cash_register_id=r.id AND public.cash_method(payment_method)=m; IF m='Dinheiro' THEN expected:=expected+r.opening_amount; END IF; report:=report||jsonb_build_object(m,jsonb_build_object('expected',expected,'counted',counted,'difference',counted-expected)); et:=et+expected; ct:=ct+counted; END LOOP; report:=jsonb_build_object('methods',report,'expected',et,'counted',ct,'difference',ct-et,'closed_by',auth.uid(),'closed_at',now()); UPDATE public.cash_registers SET status='fechado',closed_at=now(),closing_amount=ct,expected_amount=et,closing_report=report,notes=_notes WHERE id=r.id; RETURN report; END $$;
CREATE FUNCTION public.transaction_cash_ledger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.cash_registers; BEGIN IF TG_OP='DELETE' OR TG_OP='UPDATE' THEN IF EXISTS(SELECT 1 FROM public.cash_movements WHERE transaction_id=OLD.id) THEN RAISE EXCEPTION 'Lançamento conciliado no caixa não pode ser editado ou excluído'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; END IF; IF NEW.status='pago' AND NEW.amount>0 AND (TG_OP='INSERT' OR OLD.status<>'pago') THEN SELECT * INTO r FROM public.cash_registers WHERE user_id=NEW.user_id AND status='aberto' FOR UPDATE; IF FOUND THEN NEW.cash_register_id:=r.id; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_cash_transaction BEFORE INSERT OR UPDATE OR DELETE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.transaction_cash_ledger();
CREATE FUNCTION public.record_cash_transaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='pago' AND NEW.amount>0 AND NEW.cash_register_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cash_movements WHERE transaction_id=NEW.id) THEN INSERT INTO public.cash_movements(user_id,cash_register_id,movement_type,amount,payment_method,description,order_id,transaction_id,operator_id) VALUES(NEW.user_id,NEW.cash_register_id,CASE WHEN NEW.type='receita' THEN 'venda' ELSE 'pagamento' END,NEW.amount,NEW.payment_method,NEW.description,NEW.order_id,NEW.id,auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER record_cash_receipt AFTER INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.record_cash_transaction();
CREATE FUNCTION public.settle_order(_order uuid,_method text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; rid uuid; BEGIN IF auth.uid() IS NULL OR _method NOT IN('Dinheiro','Pix','Cartão de crédito','Cartão de débito','Transferência') THEN RAISE EXCEPTION 'Pagamento inválido'; END IF; SELECT id INTO rid FROM public.cash_registers WHERE user_id=public.account_owner() AND status='aberto' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Abra o caixa antes de receber'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order FOR UPDATE; IF NOT FOUND OR o.user_id<>public.account_owner() OR o.status<>'aberta' OR o.reservation_id IS NOT NULL THEN RAISE EXCEPTION 'Comanda inválida ou vinculada ao check-out'; END IF; UPDATE public.orders SET status='fechada',payment_method=_method,closed_at=now(),cash_register_id=rid WHERE id=o.id; IF o.total>0 THEN INSERT INTO public.transactions(user_id,type,category,description,amount,due_date,status,payment_method,business_unit,order_id) VALUES(o.user_id,'receita','Alimentação','Comanda #'||o.number,o.total,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'pago',_method,'lanchonete',o.id); END IF; END $$;
CREATE FUNCTION public.settle_checkout(_reservation uuid,_method text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reservations; o public.orders; rid uuid; amount numeric; BEGIN IF auth.uid() IS NULL OR _method NOT IN('Dinheiro','Pix','Cartão de crédito','Cartão de débito','Transferência') THEN RAISE EXCEPTION 'Pagamento inválido'; END IF; SELECT id INTO rid FROM public.cash_registers WHERE user_id=public.account_owner() AND status='aberto' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Abra o caixa antes de receber'; END IF; SELECT * INTO r FROM public.reservations WHERE id=_reservation FOR UPDATE; IF NOT FOUND OR r.user_id<>public.account_owner() OR r.status<>'checkin' THEN RAISE EXCEPTION 'Estadia inválida'; END IF; amount:=greatest(0,r.total_amount-r.paid_amount); IF amount>0 THEN INSERT INTO public.transactions(user_id,type,category,description,amount,due_date,status,payment_method,business_unit,reservation_id) VALUES(r.user_id,'receita','Hospedagem','Check-out — '||r.guest_name,amount,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'pago',_method,'pousada',r.id); END IF; FOR o IN SELECT * FROM public.orders WHERE reservation_id=r.id AND status='aberta' ORDER BY id FOR UPDATE LOOP UPDATE public.orders SET status='fechada',payment_method=_method,closed_at=now(),cash_register_id=rid WHERE id=o.id; IF o.total>0 THEN INSERT INTO public.transactions(user_id,type,category,description,amount,due_date,status,payment_method,business_unit,order_id,reservation_id) VALUES(r.user_id,'receita','Alimentação','Comanda #'||o.number||' — check-out',o.total,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'pago',_method,'lanchonete',o.id,r.id); END IF; END LOOP; UPDATE public.reservations SET status='finalizada',paid_amount=total_amount WHERE id=r.id; UPDATE public.rooms SET status='limpeza' WHERE id=r.room_id; END $$;
REVOKE ALL ON FUNCTION public.open_cash(numeric,text),public.move_cash(uuid,text,numeric,text),public.close_cash(uuid,jsonb,text),public.settle_order(uuid,text),public.settle_checkout(uuid,text),public.transaction_cash_ledger(),public.record_cash_transaction() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.open_cash(numeric,text),public.move_cash(uuid,text,numeric,text),public.close_cash(uuid,jsonb,text),public.settle_order(uuid,text),public.settle_checkout(uuid,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.cash_movements;